def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line.

    Trailing notes may contain numbers ("Stop Off: $100.00 (1 extra stop)",
    "Detention: $75.00/hr after 2 hrs free"), so a dollar-denominated amount
    comes first on the line and must win over those note numbers. When there is
    no dollar sign, the amount is the first number ("1800.00 USD").
    """
    money = _MONEY.search(value)
    if money:
        return Decimal(money.group(1).replace(",", ""))
    amounts = _NUMBER.findall(value)
    if not amounts:
        raise RateConError(f"no amount in {value!r}")
    return Decimal(amounts[0].replace(",", ""))

def test_trailing_note_numbers_are_not_read_as_the_amount():
    text = SIMPLE.replace(
        "Total Carrier Pay",
        "Stop Off: $100.00 (1 extra stop)\n"
        "Detention: $75.00/hr after 2 hrs free\n"
        "Total Carrier Pay",
    ).replace("$2,110.25", "$2,210.25")
    con = parse_rate_confirmation(text)
    assert con.charges["stop off"] == Decimal("100.00")
    assert con.rates["detention"] == Decimal("75.00")
    assert con.charges["linehaul"] == Decimal("1800.00")
    assert con.charges["fuel surcharge"] == Decimal("310.25")


def test_hartline_multistop_rate_con_ties_out():
    con = parse_rate_confirmation(HARTLINE_LOAD)
    assert con.load_number == "TW-88412"
    assert con.charges == {
        "linehaul": Decimal("2150.00"),
        "fuel surcharge": Decimal("412.50"),
        "stop off": Decimal("100.00"),
        "lumper": Decimal("185.00"),
    }
    assert con.rates == {"detention": Decimal("75.00")}
    assert con.total == Decimal("2847.50")


def test_amounts_without_trailing_notes_are_unchanged():
    con = parse_rate_confirmation(SIMPLE)
    assert con.charges == {
        "linehaul": Decimal("1800.00"),
        "fuel surcharge": Decimal("310.25"),
    }
    assert con.rates == {}
    assert con.total == Decimal("2110.25")


